import itertools

def check_f_solvable(c2, c1, c0, d, max_k, search_range):
    def f_actual(x):
        if d == 1: return x + c0
        if d == 2: return x**2 + c1*x + c0
        if d == 3: return x**3 + c2*x**2 + c1*x + c0
        return x**d + c2*x**(d-1) + c1*x**(d-2) + c0

    for k in range(1, max_k + 1):
        for combo in itertools.combinations(range(-search_range, search_range+1), k+1):
            for i in range(k+1):
                ak_plus_1 = combo[i]
                others = [x for j, x in enumerate(combo) if j != i]
                sum_f = sum(f_actual(x) for x in others)
                if f_actual(ak_plus_1) == sum_f:
                    return True
    return False

c2, c1, c0, d, max_k = 0, 2, -2, 3, 3
print(check_f_solvable(c2, c1, c0, d, max_k, 50))
